package com.kovian.finance.debt.api;
import com.kovian.finance.debt.domain.*; import com.kovian.finance.debt.repository.*; import com.kovian.finance.security.CurrentUser; import org.springframework.http.HttpStatus; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/debts") public class DebtController {final DebtRepository debts; final DebtInstallmentRepository installments; public DebtController(DebtRepository d,DebtInstallmentRepository i){debts=d;installments=i;} record CreateRequest(UUID ownerId,String name,DebtType debtType,BigDecimal principalAmount,BigDecimal annualInterestRate,LocalDate startDate,LocalDate endDate,int totalInstallments){}
@PostMapping @Transactional public Debt create(@RequestBody CreateRequest r){UUID owner=CurrentUser.ownerId();if(r.ownerId()!=null&&!owner.equals(r.ownerId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation");if(r.name()==null||r.name().isBlank()||r.debtType()==null||r.principalAmount()==null||r.principalAmount().signum()<=0||r.totalInstallments()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid debt request");var start=r.startDate()==null?LocalDate.now():r.startDate();var d=debts.save(new Debt(owner,r.name(),r.debtType(),r.principalAmount(),r.annualInterestRate(),start,r.endDate(),r.totalInstallments()));var part=r.principalAmount().divide(BigDecimal.valueOf(r.totalInstallments()),4,RoundingMode.HALF_UP);for(int n=1;n<=r.totalInstallments();n++){var amount=n==r.totalInstallments()?r.principalAmount().subtract(part.multiply(BigDecimal.valueOf(n-1))):part;installments.save(new DebtInstallment(owner,d.getId(),n,start.plusMonths(n),amount,BigDecimal.ZERO));}return d;}
@GetMapping public List<Debt> list(@RequestParam(required=false) UUID ownerId){UUID current=CurrentUser.ownerId();if(ownerId!=null&&!current.equals(ownerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation");return debts.findByOwnerIdOrderByName(current);} @GetMapping("/{id}/installments") public List<DebtInstallment> installments(@PathVariable UUID id){UUID owner=CurrentUser.ownerId();debts.findByIdAndOwnerId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Debt not found"));return installments.findByDebtIdOrderByDueDate(id);} @PostMapping("/{id}/pay/{installmentId}") @Transactional public void pay(@PathVariable UUID id,@PathVariable UUID installmentId,@RequestParam(required=false) UUID ownerId){UUID current=CurrentUser.ownerId();if(ownerId!=null&&!current.equals(ownerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation");var d=debts.findByIdAndOwnerId(id,current).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Debt not found"));var i=installments.findByIdAndOwnerId(installmentId,current).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Installment not found"));if(!i.getDebtId().equals(d.getId())||i.getStatus()!=InstallmentStatus.PENDING)throw new IllegalArgumentException("Invalid installment");d.pay(i.getAmount());i.pay(null);}}
